arguments.content:
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

variable "config_path" {
  description = "Path to the ClearLedger deployment configuration (config.json)."
  type        = string
  default     = "/workspace/config/config.json"
}

locals {
  cfg = jsondecode(file(var.config_path))

  prefix       = local.cfg.resource_prefix
  region       = local.cfg.region
  endpoint     = local.cfg.aws_endpoint_url
  db_name      = local.cfg.db_name
  db_username  = local.cfg.db_username
  db_password  = local.cfg.db_password
  api_image    = local.cfg.api_image
  proj_image   = local.cfg.projector_image
  relay_image  = local.cfg.relay_image
  arch_image   = local.cfg.archiver_image
  account_id   = data.aws_caller_identity.current.account_id
  azs          = ["${local.cfg.region}a", "${local.cfg.region}b"]
  vpc_cidr     = "10.42.0.0/16"
  public_cidrs = ["10.42.0.0/24", "10.42.1.0/24"]
  priv_cidrs   = ["10.42.10.0/24", "10.42.11.0/24"]

  tags = {
    ClearLedgerDeployment = local.cfg.resource_prefix
    Project               = "clearledger"
  }
}

provider "aws" {
  region     = local.region
  access_key = "test"
  secret_key = "test"

  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = false
  s3_use_path_style           = true

  endpoints {
    cloudwatchlogs = local.endpoint
    cognitoidp     = local.endpoint
    dynamodb       = local.endpoint
    ec2            = local.endpoint
    ecs            = local.endpoint
    elasticache    = local.endpoint
    elbv2          = local.endpoint
    iam            = local.endpoint
    kms            = local.endpoint
    lambda         = local.endpoint
    rds            = local.endpoint
    s3             = local.endpoint
    scheduler      = local.endpoint
    sqs            = local.endpoint
    sts            = local.endpoint
  }

  default_tags {
    tags = local.tags
  }
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "${local.prefix}-vpc" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.prefix}-igw" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "${local.prefix}-public-${local.azs[count.index]}", Tier = "public" }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.priv_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = { Name = "${local.prefix}-private-${local.azs[count.index]}", Tier = "private" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = { Name = "${local.prefix}-public-rt" }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.prefix}-private-rt" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are declared inline so that Terraform owns the full
# rule set and removes any out-of-band additions on every apply.
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB: HTTP in from internet, 8080 out to API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = { Name = "${local.prefix}-alb" }
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks: 8080 from ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API traffic from ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane (HTTPS)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "AWS control plane endpoint"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Valkey"
    from_port   = 6379
    to_port     = 6399
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Local RDS endpoint proxy range"
    from_port   = 7001
    to_port     = 7099
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${local.prefix}-ecs" }
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL: 5432 from API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "PostgreSQL from in-VPC workers"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress = []

  tags = { Name = "${local.prefix}-rds" }
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey: 6379 from API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "Valkey from in-VPC workers"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress = []

  tags = { Name = "${local.prefix}-valkey" }
}

locals {
  kms_purposes = {
    database   = "RDS PostgreSQL storage encryption"
    messaging  = "SQS main queue and DLQ encryption"
    projection = "DynamoDB projection table encryption"
    audit      = "S3 audit archive encryption"
  }

  log_groups = {
    api       = "/clearledger/${local.prefix}/api"
    projector = "/clearledger/${local.prefix}/projector"
    relay     = "/clearledger/${local.prefix}/outbox-relay"
    archiver  = "/clearledger/${local.prefix}/audit-archiver"
  }
}

resource "aws_kms_key" "this" {
  for_each = local.kms_purposes

  description             = "${local.prefix} ${each.key}: ${each.value}"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = { Name = "${local.prefix}-${each.key}" }
}

resource "aws_kms_alias" "this" {
  for_each = local.kms_purposes

  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_groups

  name              = each.value
  retention_in_days = 14

  tags = { Name = "${local.prefix}-${each.key}-logs" }
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL (system of record)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.prefix}-db-subnets"
  description = "ClearLedger PostgreSQL private subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = { Name = "${local.prefix}-db-subnets" }
}

resource "aws_db_instance" "main" {
  identifier     = "${local.prefix}-postgres"
  engine         = "postgres"
  engine_version = "16.3"
  instance_class = "db.t4g.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.this["database"].arn

  db_name  = local.db_name
  username = local.db_username
  password = local.db_password

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period  = 1
  skip_final_snapshot      = true
  deletion_protection      = false
  apply_immediately        = true
  delete_automated_backups = true

  tags = { Name = "${local.prefix}-postgres" }

  lifecycle {
    # The instance holds committed ledger data; never let cosmetic/emulator
    # drift on these attributes force a replacement.
    ignore_changes = [engine_version, availability_zone, snapshot_identifier, kms_key_id, storage_type, allocated_storage]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "projections" {
  name         = local.names.table
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  attribute {
    name = "GSI1PK"
    type = "S"
  }

  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = { Name = local.names.table }
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.prefix}-cache-subnets"
  description = "ClearLedger Valkey private subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = { Name = "${local.prefix}-cache-subnets" }
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id = "${local.prefix}-valkey"
  description          = "ClearLedger settlement projection cache"

  engine             = "valkey"
  engine_version     = "8.0"
  node_type          = "cache.t4g.micro"
  num_cache_clusters = 1
  port               = 6379

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.valkey.id]

  automatic_failover_enabled = false
  multi_az_enabled           = false
  apply_immediately          = true

  tags = { Name = "${local.prefix}-valkey" }

  lifecycle {
    # The local control plane may relocate the endpoint port; never replace
    # the cache because of it.
    ignore_changes = [port, engine_version, parameter_group_name]
  }
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "audit" {
  bucket        = local.names.bucket
  force_destroy = true

  tags = { Name = local.names.bucket }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket = aws_s3_bucket.audit.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue + DLQ
# ---------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  name                      = local.names.dlq
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600

  tags = { Name = local.names.dlq }
}

resource "aws_sqs_queue" "main" {
  name                       = local.names.queue
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = { Name = local.names.queue }
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.prefix}-users"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  tags = { Name = "${local.prefix}-users" }
}

resource "aws_cognito_resource_server" "clearledger" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.prefix}-clearledger-api"

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }

  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }

  scope {
    scope_name        = "admin"
    scope_description = "Rebuild settlement projections"
  }
}

locals {
  oauth_clients = ["read", "write", "admin"]
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(local.oauth_clients)

  name         = "${local.prefix}-${each.key}"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["${aws_cognito_resource_server.clearledger.identifier}/${each.key}"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]

  access_token_validity = 60
  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
  id_token_validity      = 60
  refresh_token_validity = 1
}

locals {
  issuer_url     = "${local.endpoint}/${aws_cognito_user_pool.main.id}"
  jwks_url       = "${local.endpoint}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  token_endpoint = "${local.endpoint}/cognito-idp/oauth2/token"
}

locals {
  database_url = "postgres://${local.db_username}:${local.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.db_name}"
  valkey_url   = "redis://${aws_elasticache_replication_group.valkey.primary_endpoint_address}:${aws_elasticache_replication_group.valkey.port}"

  common_env = {
    AWS_REGION            = local.region
    AWS_DEFAULT_REGION    = local.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = local.endpoint
  }

  api_env = merge(local.common_env, {
    PORT                 = "8080"
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CACHE_TTL_SECONDS    = "90"
    AUTH_ISSUER          = local.issuer_url
    AUTH_AUDIENCES       = join(",", [for c in local.oauth_clients : aws_cognito_user_pool_client.this[c].id])
    AUTH_JWKS_URL        = local.jwks_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["api"].name
  })

  projector_env = merge(local.common_env, {
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
  })

  relay_env = merge(local.common_env, {
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    OUTBOX_BATCH_SIZE    = "50"
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
  })

  archiver_env = merge(local.common_env, {
    DATABASE_URL         = local.database_url
    AUDIT_BUCKET         = aws_s3_bucket.audit.bucket
    AUDIT_PREFIX         = "ledger-audit/"
    AUDIT_BATCH_SIZE     = "100"
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
  })
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------

resource "aws_lb" "api" {
  name               = "${local.prefix}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
  idle_timeout       = 60

  tags = { Name = "${local.prefix}-alb" }
}

resource "aws_lb_target_group" "api" {
  name        = "${local.prefix}-api"
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 5

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = { Name = "${local.prefix}-api" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = { Name = "${local.prefix}-http" }
}

# ---------------------------------------------------------------------------
# ECS Fargate API service
# ---------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = { Name = "${local.prefix}-cluster" }
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.prefix}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.this["ecs_execution"].arn
  task_role_arn            = aws_iam_role.this["ecs_task"].arn

  container_definitions = jsonencode([{
    name      = "api"
    image     = local.api_image
    essential = true

    portMappings = [{
      containerPort = 8080
      hostPort      = 8080
      protocol      = "tcp"
    }]

    environment = [for k in sort(keys(local.api_env)) : { name = k, value = local.api_env[k] }]

    logConfiguration = {
      logDriver = "awslogs"
      options = {
        "awslogs-group"         = aws_cloudwatch_log_group.this["api"].name
        "awslogs-region"        = local.region
        "awslogs-stream-prefix" = "api"
      }
    }
  }])

  tags = { Name = "${local.prefix}-api" }
}

resource "aws_ecs_service" "api" {
  name            = "${local.prefix}-api"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  launch_type     = "FARGATE"
  desired_count   = 2

  deployment_minimum_healthy_percent = 50
  deployment_maximum_percent         = 200
  health_check_grace_period_seconds  = 60
  wait_for_steady_state              = false

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  depends_on = [aws_lb_listener.http, aws_iam_role_policy.this]

  tags = { Name = "${local.prefix}-api" }
}

# ---------------------------------------------------------------------------
# Lambda workers
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "projector" {
  function_name = local.names.projector_fn
  package_type  = "Image"
  image_uri     = local.proj_image
  role          = aws_iam_role.this["projector"].arn
  timeout       = 3
  memory_size   = 256

  environment {
    variables = local.projector_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  depends_on = [aws_iam_role_policy.this]

  tags = { Name = local.names.projector_fn }
}

resource "aws_lambda_function" "relay" {
  function_name = local.names.relay_fn
  package_type  = "Image"
  image_uri     = local.relay_image
  role          = aws_iam_role.this["relay"].arn
  timeout       = 60
  memory_size   = 256

  environment {
    variables = local.relay_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  depends_on = [aws_iam_role_policy.this]

  tags = { Name = local.names.relay_fn }
}

resource "aws_lambda_function" "archiver" {
  function_name = local.names.archiver_fn
  package_type  = "Image"
  image_uri     = local.arch_image
  role          = aws_iam_role.this["archiver"].arn
  timeout       = 60
  memory_size   = 256

  environment {
    variables = local.archiver_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  depends_on = [aws_iam_role_policy.this]

  tags = { Name = local.names.archiver_fn }
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]

  tags = { Name = "${local.prefix}-projector-esm" }
}

# ---------------------------------------------------------------------------
# EventBridge Scheduler
# ---------------------------------------------------------------------------

resource "aws_scheduler_schedule" "outbox" {
  name        = "${local.prefix}-outbox-relay"
  group_name  = "default"
  description = "Relay committed outbox rows to SQS every minute"
  state       = "ENABLED"

  schedule_expression = "rate(1 minute)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "${local.prefix}-outbox-schedule" })

    retry_policy {
      maximum_retry_attempts       = 0
      maximum_event_age_in_seconds = 60
    }
  }
}

resource "aws_scheduler_schedule" "archive" {
  name        = "${local.prefix}-audit-archiver"
  group_name  = "default"
  description = "Archive published ledger events to S3 every five minutes"
  state       = "ENABLED"

  schedule_expression = "rate(5 minutes)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "${local.prefix}-archive-schedule" })

    retry_policy {
      maximum_retry_attempts       = 0
      maximum_event_age_in_seconds = 60
    }
  }
}

