#!/usr/bin/env python3
"""Small ClearLedger API test client."""
import json, sys, uuid, base64, urllib.request, urllib.parse, datetime

M = json.load(open("/workspace/submission/manifest.json" if len(sys.argv) < 99 else ""))
BASE = M["service_url"]
_tok = {}


def token(kind):
    if kind in _tok:
        return _tok[kind]
    c = M["auth"]["clients"][kind]
    data = urllib.parse.urlencode({"grant_type": "client_credentials", "scope": c["scope"]}).encode()
    req = urllib.request.Request(M["auth"]["token_endpoint"], data=data, method="POST")
    basic = base64.b64encode(f'{c["client_id"]}:{c["client_secret"]}'.encode()).decode()
    req.add_header("Authorization", "Basic " + basic)
    req.add_header("Content-Type", "application/x-www-form-urlencoded")
    t = json.load(urllib.request.urlopen(req))["access_token"]
    _tok[kind] = t
    return t


def call(method, path, body=None, kind=None, headers=None):
    req = urllib.request.Request(BASE + path, method=method,
                                 data=json.dumps(body).encode() if body is not None else None)
    if kind:
        req.add_header("Authorization", "Bearer " + token(kind))
    if body is not None:
        req.add_header("Content-Type", "application/json")
    for k, v in (headers or {}).items():
        req.add_header(k, v)
    try:
        r = urllib.request.urlopen(req, timeout=20)
        code, hdrs, raw = r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        code, hdrs, raw = e.code, dict(e.headers), e.read()
    try:
        b = json.loads(raw)
    except Exception:
        b = raw.decode(errors="replace")
    return code, hdrs, b


def create(sid=None, acct="ACC-001", ref="REF-001", d="BANKA", c="BANKB", key=None):
    sid = sid or str(uuid.uuid4())
    return sid, call("POST", "/v1/settlements", {
        "settlementId": sid, "accountId": acct, "reference": ref, "debitParty": d,
        "creditParty": c, "expectedVersion": 0}, "write",
        {"Idempotency-Key": key or ("idem-" + uuid.uuid4().hex), "X-Correlation-Id": "corr-" + uuid.uuid4().hex[:12]})


def entry(sid, status, ev, stage="stage-x", memo=None, key=None, occurred=None, entry_id=None):
    occurred = occurred or datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    body = {"entryId": entry_id or str(uuid.uuid4()), "status": status, "clearingStage": stage,
            "occurredAt": occurred, "expectedVersion": ev}
    if memo is not None:
        body["memo"] = memo
    return call("POST", f"/v1/settlements/{sid}/entries", body, "write",
                {"Idempotency-Key": key or ("idem-" + uuid.uuid4().hex), "X-Correlation-Id": "corr-" + uuid.uuid4().hex[:12]})

