#!/usr/bin/env python3
"""ClearLedger data-plane / control-plane convergence.

PostgreSQL is the system of record. This script converges every derived store
against it and removes out-of-band control-plane drift that Terraform does not
own exclusively:

  1. IAM: strip out-of-band inline/attached policies from the six workload
     roles and delete detached <prefix>-* customer-managed policies.
  2. Security groups: revoke forbidden egress rules (rds/valkey: none, alb: no
     0.0.0.0/0, ::/0 or all-protocol egress).
  3. Outbox: drain unpublished rows through the outbox_relay Lambda.
  4. SQS: wait until the projector has drained the main queue.
  5. DynamoDB: 1-to-1 STATE / EVENT#nnnnnnnn items with PostgreSQL.
  6. S3: 1-to-1 canonical NDJSON audit batches with clearledger.outbox (via the
     audit_archiver Lambda first, then deterministic repair), purging
     noncurrent versions and delete markers.
  7. Valkey: only clearledger:settlement:<id> keys, populated for every
     settlement with the canonical SettlementProjection JSON and TTL 90.

Usage: converge.py <config.json> <manifest.json>
"""
import datetime as dt
import hashlib
import json
import re
import sys
import time

import boto3
import psycopg
import redis
from botocore.config import Config

CFG = json.load(open(sys.argv[1]))
MAN = json.load(open(sys.argv[2]))
PREFIX = CFG["resource_prefix"]
EP = CFG["aws_endpoint_url"]
REGION = CFG["region"]
CACHE_TTL = 90
AUDIT_PREFIX = "ledger-audit/"
AUDIT_BATCH = 100
KEY_RE = re.compile(r"^ledger-audit/batch-(\d{8})-(\d{8})-([0-9a-f]{16})\.ndjson$")

BOTO_CFG = Config(retries={"max_attempts": 6, "mode": "standard"}, read_timeout=180, connect_timeout=10)


def log(msg):
    print(f"[converge] {msg}", file=sys.stderr, flush=True)


def client(name):
    return boto3.client(name, endpoint_url=EP, region_name=REGION,
                        aws_access_key_id="test", aws_secret_access_key="test", config=BOTO_CFG)


def db():
    return psycopg.connect(
        host=MAN["database"]["endpoint"], port=MAN["database"]["port"],
        dbname=CFG["db_name"], user=CFG["db_username"], password=CFG["db_password"],
        connect_timeout=10, autocommit=True)


# ---------------------------------------------------------------------------
# Canonical serialisations (mirror the Rust workers byte-for-byte)
# ---------------------------------------------------------------------------

ENVELOPE_ORDER = ["schemaVersion", "eventId", "eventType", "aggregateType", "aggregateId",
                  "aggregateVersion", "occurredAt", "correlationId", "idempotencyKey", "data"]
DATA_ORDER = ["kind", "accountId", "reference", "debitParty", "creditParty", "entryId",
              "status", "clearingStage", "memo"]


def _ordered(obj, order):
    out = {k: obj[k] for k in order if k in obj}
    for k in obj:  # never drop unknown keys (schema forbids them anyway)
        if k not in out:
            out[k] = obj[k]
    return out


def canonical_envelope(payload):
    env = _ordered(payload, ENVELOPE_ORDER)
    if isinstance(env.get("data"), dict):
        env["data"] = _ordered(env["data"], DATA_ORDER)
    return json.dumps(env, separators=(",", ":"), ensure_ascii=False)


def rfc3339(ts, z=False):
    """chrono::DateTime::to_rfc3339_opts(SecondsFormat::AutoSi, z)."""
    ts = ts.astimezone(dt.timezone.utc)
    base = ts.strftime("%Y-%m-%dT%H:%M:%S")
    us = ts.microsecond
    if us == 0:
        frac = ""
    elif us % 1000 == 0:
        frac = ".%03d" % (us // 1000)
    else:
        frac = ".%06d" % us
    return base + frac + ("Z" if z else "+00:00")


# ---------------------------------------------------------------------------
# 1. IAM drift
# ---------------------------------------------------------------------------

def converge_iam():
    iam = client("iam")
    roles = [arn.split("/")[-1] for arn in MAN["iam"].values()]
    for role in roles:
        canonical = f"{role}-least-privilege"
        try:
            names = iam.list_role_policies(RoleName=role).get("PolicyNames", [])
        except iam.exceptions.NoSuchEntityException:
            continue
        for name in names:
            if name != canonical:
                log(f"iam: deleting out-of-band inline policy {role}/{name}")
                iam.delete_role_policy(RoleName=role, PolicyName=name)
        for ap in iam.list_attached_role_policies(RoleName=role).get("AttachedPolicies", []):
            log(f"iam: detaching out-of-band policy {ap['PolicyArn']} from {role}")
            iam.detach_role_policy(RoleName=role, PolicyArn=ap["PolicyArn"])

    paginator = iam.get_paginator("list_policies")
    for page in paginator.paginate(Scope="Local"):
        for pol in page.get("Policies", []):
            if not pol["PolicyName"].startswith(PREFIX):
                continue
            arn = pol["Arn"]
            ents = iam.list_entities_for_policy(PolicyArn=arn)
            if ents.get("PolicyRoles") or ents.get("PolicyUsers") or ents.get("PolicyGroups"):
                continue
            log(f"iam: deleting detached out-of-band policy {arn}")
            for v in iam.list_policy_versions(PolicyArn=arn).get("Versions", []):
                if not v["IsDefaultVersion"]:
                    iam.delete_policy_version(PolicyArn=arn, VersionId=v["VersionId"])
            iam.delete_policy(PolicyArn=arn)


# ---------------------------------------------------------------------------
# 2. Security-group egress drift
# ---------------------------------------------------------------------------

def converge_security_groups():
    ec2 = client("ec2")
    sgs = MAN["network"]["security_group_ids"]
    resp = ec2.describe_security_groups(GroupIds=list(sgs.values()))
    by_id = {g["GroupId"]: g for g in resp["SecurityGroups"]}
    for role, gid in sgs.items():
        g = by_id.get(gid)
        if not g:
            continue
        bad = []
        for perm in g.get("IpPermissionsEgress", []):
            if role in ("rds", "valkey"):
                bad.append(perm)
            elif role == "alb":
                open4 = any(r.get("CidrIp") == "0.0.0.0/0" for r in perm.get("IpRanges", []))
                open6 = any(r.get("CidrIpv6") == "::/0" for r in perm.get("Ipv6Ranges", []))
                if open4 or open6 or perm.get("IpProtocol") == "-1":
                    bad.append(perm)
        if bad:
            log(f"sg: revoking {len(bad)} forbidden egress rule(s) on {role} ({gid})")
            clean = []
            for p in bad:
                q = {k: v for k, v in p.items() if k in ("IpProtocol", "FromPort", "ToPort", "IpRanges",
                                                         "Ipv6Ranges", "PrefixListIds", "UserIdGroupPairs")}
                for k in ("IpRanges", "Ipv6Ranges", "PrefixListIds", "UserIdGroupPairs"):
                    if k in q and not q[k]:
                        del q[k]
                clean.append(q)
            try:
                ec2.revoke_security_group_egress(GroupId=gid, IpPermissions=clean)
            except Exception as exc:  # noqa: BLE001
                log(f"sg: revoke failed on {gid}: {exc}")


# ---------------------------------------------------------------------------
# 3. Outbox drain via outbox_relay
# ---------------------------------------------------------------------------

def invoke(fn):
    lam = client("lambda")
    r = lam.invoke(FunctionName=fn, InvocationType="RequestResponse", Payload=b"{}")
    body = r["Payload"].read()
    if r.get("FunctionError"):
        raise RuntimeError(f"{fn} failed: {body[:500]!r}")
    return body


def count(conn, sql):
    return conn.execute(sql).fetchone()[0]


def drain_outbox(conn, deadline):
    fn = MAN["workers"]["outbox_relay"]["function_name"]
    last = None
    while True:
        n = count(conn, "SELECT count(*) FROM clearledger.outbox WHERE published_at IS NULL")
        if n == 0:
            log("outbox: no unpublished rows")
            return
        if time.time() > deadline:
            raise RuntimeError(f"outbox: {n} rows still unpublished at deadline")
        log(f"outbox: {n} unpublished row(s); invoking {fn}")
        try:
            invoke(fn)
        except Exception as exc:  # noqa: BLE001
            log(f"outbox: relay invocation error: {exc}")
            time.sleep(3)
        if last is not None and n >= last:
            time.sleep(2)
        last = n


# ---------------------------------------------------------------------------
# 4. Wait for the projector to drain SQS
# ---------------------------------------------------------------------------

def wait_queue_drained(deadline):
    sqs = client("sqs")
    url = MAN["messaging"]["queue_url"]
    stable = 0
    while time.time() < deadline:
        a = sqs.get_queue_attributes(QueueUrl=url, AttributeNames=[
            "ApproximateNumberOfMessages", "ApproximateNumberOfMessagesNotVisible",
            "ApproximateNumberOfMessagesDelayed"])["Attributes"]
        total = sum(int(a.get(k, 0)) for k in a)
        if total == 0:
            stable += 1
            if stable >= 2:
                log("sqs: main queue drained")
                return True
        else:
            stable = 0
        time.sleep(1.5)
    log("sqs: main queue not fully drained before deadline; continuing")
    return False


# ---------------------------------------------------------------------------
# 5. DynamoDB projections
# ---------------------------------------------------------------------------

def S(v):
    return {"S": v}


def N(v):
    return {"N": str(int(v))}


def load_pg(conn):
    settlements = conn.execute("""
        SELECT settlement_id::text, account_id, reference, debit_party, credit_party, current_status,
               current_stage, last_entry_id::text, last_memo, version, entry_count, updated_at
          FROM clearledger.settlements ORDER BY settlement_id""").fetchall()
    events = conn.execute("""
        SELECT settlement_id::text, event_id::text, aggregate_version, event_type, correlation_id,
               occurred_at, payload
          FROM clearledger.events ORDER BY settlement_id, aggregate_version""").fetchall()
    return settlements, events


def expected_items(settlements, events):
    items = {}
    for (sid, acct, ref, dp, cp, status, stage, last_entry, last_memo, version, entry_count, updated) in settlements:
        it = {
            "PK": S(f"SETTLEMENT#{sid}"), "SK": S("STATE"),
            "GSI1PK": S(f"ACCOUNT#{acct}"), "GSI1SK": S(f"SETTLEMENT#{sid}"),
            "settlement_id": S(sid), "account_id": S(acct), "reference": S(ref),
            "debit_party": S(dp), "credit_party": S(cp), "status": S(status),
            "clearing_stage": S(stage), "version": N(version), "entry_count": N(entry_count),
            "updated_at": S(rfc3339(updated)),
        }
        if last_entry is not None:
            it["last_entry_id"] = S(last_entry)
        if last_memo is not None:
            it["last_memo"] = S(last_memo)
        items[(f"SETTLEMENT#{sid}", "STATE")] = it
    for (sid, eid, ver, etype, corr, occurred, payload) in events:
        data = payload.get("data") or {}
        it = {
            "PK": S(f"SETTLEMENT#{sid}"), "SK": S("EVENT#%08d" % ver),
            "settlement_id": S(sid), "event_id": S(eid), "version": N(ver), "event_type": S(etype),
            "status": S(data.get("status")), "clearing_stage": S(data.get("clearingStage")),
            "occurred_at": S(rfc3339(occurred)), "correlation_id": S(corr),
            "envelope": S(canonical_envelope(payload)),
        }
        if data.get("entryId") is not None:
            it["entry_id"] = S(data["entryId"])
        if data.get("memo") is not None:
            it["memo"] = S(data["memo"])
        items[(f"SETTLEMENT#{sid}", "SK" and "EVENT#%08d" % ver)] = it
    return items


def converge_dynamodb(conn):
    ddb = client("dynamodb")
    table = MAN["projections"]["table_name"]
    settlements, events = load_pg(conn)
    want = expected_items(settlements, events)

    have = {}
    kw = {"TableName": table, "ConsistentRead": True}
    while True:
        page = ddb.scan(**kw)
        for it in page.get("Items", []):
            pk = it.get("PK", {}).get("S")
            sk = it.get("SK", {}).get("S")
            have[(pk, sk)] = it
        if "LastEvaluatedKey" not in page:
            break
        kw["ExclusiveStartKey"] = page["LastEvaluatedKey"]

    deleted = written = 0
    for key, it in have.items():
        if key not in want:
            ddb.delete_item(TableName=table, Key={"PK": it["PK"], "SK": it["SK"]})
            deleted += 1
    for key, it in want.items():
        if have.get(key) != it:
            ddb.put_item(TableName=table, Item=it)
            written += 1
    log(f"dynamodb: {len(want)} expected item(s); wrote {written}, deleted {deleted}")
    return settlements


# ---------------------------------------------------------------------------
# 6. S3 audit archive
# ---------------------------------------------------------------------------

def list_versions(s3, bucket):
    versions, markers = [], []
    kw = {"Bucket": bucket}
    while True:
        page = s3.list_object_versions(**kw)
        versions.extend(page.get("Versions", []) or [])
        markers.extend(page.get("DeleteMarkers", []) or [])
        if not page.get("IsTruncated"):
            break
        kw["KeyMarker"] = page.get("NextKeyMarker")
        if page.get("NextVersionIdMarker"):
            kw["VersionIdMarker"] = page["NextVersionIdMarker"]
        else:
            kw.pop("VersionIdMarker", None)
    return versions, markers


def batch_body(rows):
    return "".join(canonical_envelope(p) + "\n" for (_, p) in rows).encode()


def batch_key(rows, body):
    return "%sbatch-%08d-%08d-%s.ndjson" % (AUDIT_PREFIX, rows[0][0], rows[-1][0],
                                            hashlib.sha256(body).hexdigest()[:16])


def run_archiver(conn, deadline):
    fn = MAN["workers"]["audit_archiver"]["function_name"]
    for _ in range(50):
        n = count(conn, "SELECT count(*) FROM clearledger.outbox WHERE published_at IS NOT NULL AND archived_at IS NULL")
        if n == 0 or time.time() > deadline:
            return
        log(f"s3: {n} published row(s) awaiting archival; invoking {fn}")
        try:
            invoke(fn)
        except Exception as exc:  # noqa: BLE001
            log(f"s3: archiver invocation error: {exc}")
            return


def s3_pass(conn, s3, bucket):
    """One reconciliation pass. Returns number of mutations performed."""
    rows = conn.execute("""SELECT seq, payload, published_at IS NOT NULL, archived_at IS NOT NULL
                             FROM clearledger.outbox ORDER BY seq""").fetchall()
    by_seq = {r[0]: r for r in rows}
    seqs = [r[0] for r in rows]

    versions, markers = list_versions(s3, bucket)
    latest = [v for v in versions if v.get("IsLatest")]
    changes = 0

    # Validate current objects.
    valid = []  # (first, last, key)
    for v in latest:
        key = v["Key"]
        m = KEY_RE.match(key)
        ok = False
        if m:
            first, last, digest = int(m.group(1)), int(m.group(2)), m.group(3)
            if first <= last:
                try:
                    body = s3.get_object(Bucket=bucket, Key=key, VersionId=v["VersionId"])["Body"].read()
                except Exception:  # noqa: BLE001
                    body = None
                if body is not None and hashlib.sha256(body).hexdigest()[:16] == digest:
                    in_range = [s for s in seqs if first <= s <= last]
                    if in_range and in_range[0] == first and in_range[-1] == last \
                            and all(by_seq[s][2] for s in in_range):
                        expect = batch_body([(s, by_seq[s][1]) for s in in_range])
                        ok = body == expect
        if ok:
            valid.append((first, last, key))

    # Choose a disjoint subset (earliest first, then widest).
    valid.sort(key=lambda t: (t[0], -(t[1] - t[0])))
    keep, covered_to = [], -1
    for first, last, key in valid:
        if first > covered_to:
            keep.append((first, last, key))
            covered_to = last
    keep_keys = {k for _, _, k in keep}

    covered = set()
    for first, last, _ in keep:
        covered.update(s for s in seqs if first <= s <= last)

    # Mark rows covered by kept objects as archived.
    need_mark = [s for s in covered if not by_seq[s][3]]
    if need_mark:
        conn.execute("UPDATE clearledger.outbox SET archived_at = NOW() "
                     "WHERE seq = ANY(%s) AND archived_at IS NULL", (need_mark,))
        changes += len(need_mark)

    # Write deterministic batches for published rows not covered by any object.
    runs, cur = [], []
    for s in seqs:
        published = by_seq[s][2]
        if s in covered or not published:
            if cur:
                runs.append(cur)
                cur = []
            continue
        cur.append(s)
        if len(cur) == AUDIT_BATCH:
            runs.append(cur)
            cur = []
    if cur:
        runs.append(cur)

    for run in runs:
        brows = [(s, by_seq[s][1]) for s in run]
        body = batch_body(brows)
        key = batch_key(brows, body)
        s3.put_object(Bucket=bucket, Key=key, Body=body, ContentType="application/x-ndjson")
        keep_keys.add(key)
        conn.execute("UPDATE clearledger.outbox SET archived_at = NOW() "
                     "WHERE seq = ANY(%s) AND archived_at IS NULL", (run,))
        log(f"s3: wrote {key} ({len(run)} row(s))")
        changes += 1

    # Purge everything that is not the single current version of a kept batch.
    versions, markers = list_versions(s3, bucket)
    doomed = [(v["Key"], v["VersionId"]) for v in versions
              if not (v.get("IsLatest") and v["Key"] in keep_keys)]
    doomed += [(m["Key"], m["VersionId"]) for m in markers]
    for i in range(0, len(doomed), 500):
        chunk = doomed[i:i + 500]
        s3.delete_objects(Bucket=bucket, Delete={
            "Objects": [{"Key": k, "VersionId": vid} for k, vid in chunk], "Quiet": True})
    if doomed:
        log(f"s3: purged {len(doomed)} stray/noncurrent version(s) and delete marker(s)")
        changes += len(doomed)
    return changes


def converge_s3(conn, deadline):
    s3 = client("s3")
    bucket = MAN["audit"]["bucket_name"]
    run_archiver(conn, deadline)
    for i in range(6):
        changes = s3_pass(conn, s3, bucket)
        if changes == 0:
            log(f"s3: archive converged (pass {i + 1})")
            return
        time.sleep(1)
    log("s3: archive still changing after 6 passes")


# ---------------------------------------------------------------------------
# 7. Valkey cache
# ---------------------------------------------------------------------------

def projection_json(row):
    (sid, acct, ref, dp, cp, status, stage, last_entry, last_memo, version, entry_count, updated) = row
    p = {"settlementId": sid, "accountId": acct, "reference": ref, "debitParty": dp,
         "creditParty": cp, "status": status, "clearingStage": stage}
    if last_entry is not None:
        p["lastEntryId"] = last_entry
    if last_memo is not None:
        p["lastMemo"] = last_memo
    p["version"] = version
    p["entryCount"] = entry_count
    p["updatedAt"] = rfc3339(updated, z=True)
    return json.dumps(p, separators=(",", ":"), ensure_ascii=False)


def converge_valkey(conn):
    r = redis.Redis(host=MAN["cache"]["endpoint"], port=int(MAN["cache"]["port"]),
                    socket_timeout=10, socket_connect_timeout=10)
    settlements, _ = load_pg(conn)
    want = {f"clearledger:settlement:{row[0]}": projection_json(row) for row in settlements}
    stray = [k for k in r.scan_iter(match="*", count=1000) if k.decode(errors="replace") not in want]
    for i in range(0, len(stray), 500):
        r.delete(*stray[i:i + 500])
    pipe = r.pipeline(transaction=False)
    for k, v in want.items():
        pipe.set(k, v, ex=CACHE_TTL)
    pipe.execute()
    log(f"valkey: populated {len(want)} key(s), purged {len(stray)} stray key(s)")


# ---------------------------------------------------------------------------

def main():
    start = time.time()
    budget = float(sys.argv[3]) if len(sys.argv) > 3 else 300.0
    deadline = start + budget

    converge_iam()
    converge_security_groups()

    with db() as conn:
        drain_outbox(conn, deadline)
        wait_queue_drained(min(deadline, time.time() + 60))
        converge_dynamodb(conn)
        converge_s3(conn, deadline)
        # Late outbox rows (live traffic) -> publish again before the final sweep.
        drain_outbox(conn, deadline)
        wait_queue_drained(min(deadline, time.time() + 30))
        converge_dynamodb(conn)
        converge_valkey(conn)
    log(f"done in {time.time() - start:.1f}s")


if __name__ == "__main__":
    main()

"""Independent invariant checker for derived stores vs PostgreSQL."""
import json, re, hashlib, boto3, redis, psycopg, sys
M = json.load(open("/workspace/submission/manifest.json"))
C = json.load(open("/workspace/config/config.json"))
kw = dict(endpoint_url="http://aws:4566", region_name="us-east-1", aws_access_key_id="test", aws_secret_access_key="test")
s3 = boto3.client("s3", **kw); ddb = boto3.client("dynamodb", **kw)
B = M["audit"]["bucket_name"]; T = M["projections"]["table_name"]
conn = psycopg.connect(host=M["database"]["endpoint"], port=M["database"]["port"], dbname=C["db_name"], user=C["db_username"], password=C["db_password"], autocommit=True)
errs = []
sett = {str(r[0]): r for r in conn.execute("select settlement_id, account_id, current_status, version, last_memo from clearledger.settlements")}
evs = conn.execute("select settlement_id::text, aggregate_version, payload from clearledger.events").fetchall()
out = conn.execute("select seq, payload, published_at, archived_at from clearledger.outbox order by seq").fetchall()
# outbox
for seq, p, pub, arc in out:
    if pub is None: errs.append(f"outbox {seq} unpublished")
    if arc is None: errs.append(f"outbox {seq} unarchived")
# dynamo
items = []
k = {"TableName": T}
while True:
    pg = ddb.scan(**k); items += pg["Items"]
    if "LastEvaluatedKey" not in pg: break
    k["ExclusiveStartKey"] = pg["LastEvaluatedKey"]
want = {(f"SETTLEMENT#{s}", "STATE") for s in sett} | {(f"SETTLEMENT#{s}", "EVENT#%08d" % v) for s, v, _ in evs}
have = {(i["PK"]["S"], i["SK"]["S"]) for i in items}
if want != have: errs.append(f"dynamo keys differ: missing={want-have} extra={have-want}")
for i in items:
    if i["SK"]["S"] == "STATE":
        s = sett.get(i["PK"]["S"].split("#")[1])
        if s and (i["status"]["S"] != s[2] or int(i["version"]["N"]) != s[3] or i["GSI1PK"]["S"] != "ACCOUNT#" + s[1] or i.get("last_memo", {}).get("S") != s[4]):
            errs.append(f"dynamo STATE mismatch {i['PK']['S']}")
# valkey
r = redis.Redis(host=M["cache"]["endpoint"], port=M["cache"]["port"])
keys = {k.decode() for k in r.scan_iter("*")}
wantk = {f"clearledger:settlement:{s}" for s in sett}
if keys != wantk: errs.append(f"valkey keys differ: missing={wantk-keys} extra={keys-wantk}")
for kk in wantk & keys:
    ttl = r.ttl(kk); v = json.loads(r.get(kk))
    if not (0 < ttl <= 90): errs.append(f"bad ttl {kk} {ttl}")
    s = sett[kk.split(":")[-1]]
    if v.get("version") != s[3] or v.get("status") != s[2]: errs.append(f"valkey stale {kk}")
# s3
vs = s3.list_object_versions(Bucket=B)
if vs.get("DeleteMarkers"): errs.append(f"delete markers: {len(vs['DeleteMarkers'])}")
if any(not v["IsLatest"] for v in vs.get("Versions", [])): errs.append("noncurrent versions present")
seen = {}
payload = {seq: p for seq, p, _, _ in out}
ranges = []
for v in vs.get("Versions", []):
    m = re.match(r"^ledger-audit/batch-(\d{8})-(\d{8})-([0-9a-f]{16})\.ndjson$", v["Key"])
    if not m: errs.append(f"bad key {v['Key']}"); continue
    body = s3.get_object(Bucket=B, Key=v["Key"])["Body"].read()
    if hashlib.sha256(body).hexdigest()[:16] != m.group(3): errs.append(f"bad hash {v['Key']}")
    f, l = int(m.group(1)), int(m.group(2)); ranges.append((f, l))
    lines = [json.loads(x) for x in body.decode().splitlines()]
    exp = [s for s in payload if f <= s <= l]
    if len(lines) != len(exp): errs.append(f"gap in {v['Key']}")
    for s, ln in zip(exp, lines):
        if ln != payload[s]: errs.append(f"payload mismatch seq {s}")
        seen[s] = seen.get(s, 0) + 1
ranges.sort()
for a, b in zip(ranges, ranges[1:]):
    if b[0] <= a[1]: errs.append(f"overlap {a} {b}")
for s in payload:
    if seen.get(s) != 1: errs.append(f"seq {s} archived {seen.get(s,0)} times")
print("OK" if not errs else "\n".join(errs[:40]))
sys.exit(1 if errs else 0)

#!/usr/bin/env python3
"""Prefix-scoped sweep of ClearLedger resources (Terraform-managed leftovers
and out-of-band operational resources). Never touches anything that does not
belong to the active resource_prefix (e.g. cl-base-* baseline resources).

Usage: sweep.py <config.json>
"""
import json
import re
import sys
import time

import boto3
from botocore.config import Config

CFG = json.load(open(sys.argv[1]))
PREFIX = CFG["resource_prefix"]
EP = CFG["aws_endpoint_url"]
REGION = CFG["region"]
TAG_KEY = "ClearLedgerDeployment"
NAME_RE = re.compile(r"^" + re.escape(PREFIX) + r"([-_.]|$)")
LOG_RE = re.compile(r"(^|/)" + re.escape(PREFIX) + r"([-_./]|$)")
BOTO_CFG = Config(retries={"max_attempts": 5, "mode": "standard"}, read_timeout=60, connect_timeout=10)


def log(msg):
    print(f"[sweep] {msg}", file=sys.stderr, flush=True)


def c(name):
    return boto3.client(name, endpoint_url=EP, region_name=REGION, aws_access_key_id="test",
                        aws_secret_access_key="test", config=BOTO_CFG)


def mine(name):
    return bool(name) and bool(NAME_RE.match(name))


def safe(desc, fn, *a, **kw):
    try:
        return fn(*a, **kw)
    except Exception as exc:  # noqa: BLE001
        msg = str(exc)
        if not any(s in msg for s in ("NotFound", "NoSuch", "does not exist", "not found", "ResourceNotFound")):
            log(f"{desc}: {msg[:200]}")
        return None


def tags_mine(tags):
    if isinstance(tags, dict):
        return tags.get(TAG_KEY) == PREFIX
    for t in tags or []:
        if (t.get("Key") or t.get("TagKey")) == TAG_KEY and (t.get("Value") or t.get("TagValue")) == PREFIX:
            return True
    return False


# ---------------------------------------------------------------------------

def sweep_scheduler():
    s = c("scheduler")
    groups = [g["Name"] for g in (safe("scheduler groups", s.list_schedule_groups) or {}).get("ScheduleGroups", [])]
    for g in groups:
        token = None
        while True:
            kw = {"GroupName": g}
            if token:
                kw["NextToken"] = token
            resp = safe("list schedules", s.list_schedules, **kw) or {}
            for sch in resp.get("Schedules", []):
                if mine(sch["Name"]):
                    log(f"scheduler: delete {g}/{sch['Name']}")
                    safe("delete schedule", s.delete_schedule, Name=sch["Name"], GroupName=g)
            token = resp.get("NextToken")
            if not token:
                break
        if mine(g):
            log(f"scheduler: delete group {g}")
            safe("delete schedule group", s.delete_schedule_group, Name=g)


def sweep_lambda():
    lam = c("lambda")
    fns = []
    for page in lam.get_paginator("list_functions").paginate():
        fns += [f for f in page.get("Functions", []) if mine(f["FunctionName"])]
    for page in lam.get_paginator("list_event_source_mappings").paginate():
        for m in page.get("EventSourceMappings", []):
            fn = m.get("FunctionArn", "").split(":function:")[-1].split(":")[0]
            src = m.get("EventSourceArn", "").split(":")[-1]
            if mine(fn) or mine(src):
                log(f"lambda: delete event source mapping {m['UUID']}")
                safe("delete esm", lam.delete_event_source_mapping, UUID=m["UUID"])
    for f in fns:
        log(f"lambda: delete function {f['FunctionName']}")
        safe("delete function", lam.delete_function, FunctionName=f["FunctionName"])


def sweep_ecs():
    ecs = c("ecs")
    arns = (safe("list clusters", ecs.list_clusters) or {}).get("clusterArns", [])
    for arn in arns:
        name = arn.split("/")[-1]
        if not mine(name):
            continue
        svcs = (safe("list services", ecs.list_services, cluster=arn) or {}).get("serviceArns", [])
        for s in svcs:
            log(f"ecs: delete service {s}")
            safe("scale service", ecs.update_service, cluster=arn, service=s, desiredCount=0)
            safe("delete service", ecs.delete_service, cluster=arn, service=s, force=True)
        for t in (safe("list tasks", ecs.list_tasks, cluster=arn) or {}).get("taskArns", []):
            safe("stop task", ecs.stop_task, cluster=arn, task=t, reason="clearledger destroy")
        log(f"ecs: delete cluster {name}")
        for _ in range(10):
            if safe("delete cluster", ecs.delete_cluster, cluster=arn) is not None:
                break
            time.sleep(2)
    for status in ("ACTIVE", "INACTIVE"):
        token = None
        while True:
            kw = {"status": status}
            if token:
                kw["nextToken"] = token
            resp = safe("list task defs", ecs.list_task_definitions, **kw) or {}
            for td in resp.get("taskDefinitionArns", []):
                fam = td.split("/")[-1].rsplit(":", 1)[0]
                if mine(fam):
                    if status == "ACTIVE":
                        safe("deregister td", ecs.deregister_task_definition, taskDefinition=td)
                    if hasattr(ecs, "delete_task_definitions"):
                        safe("delete td", ecs.delete_task_definitions, taskDefinitions=[td])
            token = resp.get("nextToken")
            if not token:
                break


def sweep_elb():
    elb = c("elbv2")
    for lb in (safe("describe lbs", elb.describe_load_balancers) or {}).get("LoadBalancers", []):
        if mine(lb["LoadBalancerName"]):
            for ln in (safe("listeners", elb.describe_listeners, LoadBalancerArn=lb["LoadBalancerArn"]) or {}).get("Listeners", []):
                safe("delete listener", elb.delete_listener, ListenerArn=ln["ListenerArn"])
            log(f"elbv2: delete load balancer {lb['LoadBalancerName']}")
            safe("delete lb", elb.delete_load_balancer, LoadBalancerArn=lb["LoadBalancerArn"])
    for tg in (safe("describe tgs", elb.describe_target_groups) or {}).get("TargetGroups", []):
        if mine(tg["TargetGroupName"]):
            log(f"elbv2: delete target group {tg['TargetGroupName']}")
            safe("delete tg", elb.delete_target_group, TargetGroupArn=tg["TargetGroupArn"])


def sweep_rds():
    rds = c("rds")
    doomed = []
    for db in (safe("describe dbs", rds.describe_db_instances) or {}).get("DBInstances", []):
        if mine(db["DBInstanceIdentifier"]):
            log(f"rds: delete instance {db['DBInstanceIdentifier']}")
            safe("modify db", rds.modify_db_instance, DBInstanceIdentifier=db["DBInstanceIdentifier"],
                 DeletionProtection=False, ApplyImmediately=True)
            safe("delete db", rds.delete_db_instance, DBInstanceIdentifier=db["DBInstanceIdentifier"],
                 SkipFinalSnapshot=True, DeleteAutomatedBackups=True)
            doomed.append(db["DBInstanceIdentifier"])
    for _ in range(60):
        left = [d["DBInstanceIdentifier"] for d in (safe("describe dbs", rds.describe_db_instances) or {}).get("DBInstances", [])
                if d["DBInstanceIdentifier"] in doomed]
        if not left:
            break
        time.sleep(3)
    for snap in (safe("describe snapshots", rds.describe_db_snapshots) or {}).get("DBSnapshots", []):
        if mine(snap["DBSnapshotIdentifier"]) or mine(snap.get("DBInstanceIdentifier")):
            safe("delete snapshot", rds.delete_db_snapshot, DBSnapshotIdentifier=snap["DBSnapshotIdentifier"])
    for g in (safe("describe subnet groups", rds.describe_db_subnet_groups) or {}).get("DBSubnetGroups", []):
        if mine(g["DBSubnetGroupName"]):
            log(f"rds: delete subnet group {g['DBSubnetGroupName']}")
            safe("delete db subnet group", rds.delete_db_subnet_group, DBSubnetGroupName=g["DBSubnetGroupName"])
    for g in (safe("describe pgs", rds.describe_db_parameter_groups) or {}).get("DBParameterGroups", []):
        if mine(g["DBParameterGroupName"]):
            safe("delete pg", rds.delete_db_parameter_group, DBParameterGroupName=g["DBParameterGroupName"])


def sweep_elasticache():
    ec = c("elasticache")
    doomed = []
    for rg in (safe("describe rgs", ec.describe_replication_groups) or {}).get("ReplicationGroups", []):
        if mine(rg["ReplicationGroupId"]):
            log(f"elasticache: delete replication group {rg['ReplicationGroupId']}")
            safe("delete rg", ec.delete_replication_group, ReplicationGroupId=rg["ReplicationGroupId"])
            doomed.append(rg["ReplicationGroupId"])
    for cc in (safe("describe ccs", ec.describe_cache_clusters) or {}).get("CacheClusters", []):
        if mine(cc["CacheClusterId"]) and not cc.get("ReplicationGroupId"):
            safe("delete cc", ec.delete_cache_cluster, CacheClusterId=cc["CacheClusterId"])
    for _ in range(40):
        left = [r for r in (safe("describe rgs", ec.describe_replication_groups) or {}).get("ReplicationGroups", [])
                if r["ReplicationGroupId"] in doomed]
        if not left:
            break
        time.sleep(3)
    for g in (safe("describe subnet groups", ec.describe_cache_subnet_groups) or {}).get("CacheSubnetGroups", []):
        if mine(g["CacheSubnetGroupName"]):
            log(f"elasticache: delete subnet group {g['CacheSubnetGroupName']}")
            safe("delete cache subnet group", ec.delete_cache_subnet_group, CacheSubnetGroupName=g["CacheSubnetGroupName"])


def sweep_dynamodb():
    ddb = c("dynamodb")
    for page in ddb.get_paginator("list_tables").paginate():
        for t in page.get("TableNames", []):
            if mine(t):
                log(f"dynamodb: delete table {t}")
                safe("ddb protection", ddb.update_table, TableName=t, DeletionProtectionEnabled=False)
                safe("delete table", ddb.delete_table, TableName=t)


def sweep_sqs():
    sqs = c("sqs")
    urls = (safe("list queues", sqs.list_queues, QueueNamePrefix=PREFIX) or {}).get("QueueUrls", [])
    for u in urls:
        if mine(u.rstrip("/").split("/")[-1]):
            log(f"sqs: delete queue {u}")
            safe("delete queue", sqs.delete_queue, QueueUrl=u)


def purge_bucket(s3, b):
    while True:
        resp = safe("list versions", s3.list_object_versions, Bucket=b) or {}
        objs = [{"Key": v["Key"], "VersionId": v["VersionId"]} for v in resp.get("Versions", []) or []]
        objs += [{"Key": m["Key"], "VersionId": m["VersionId"]} for m in resp.get("DeleteMarkers", []) or []]
        if not objs:
            break
        for i in range(0, len(objs), 500):
            safe("delete objects", s3.delete_objects, Bucket=b, Delete={"Objects": objs[i:i + 500], "Quiet": True})
    while True:
        resp = safe("list objects", s3.list_objects_v2, Bucket=b) or {}
        objs = [{"Key": o["Key"]} for o in resp.get("Contents", []) or []]
        if not objs:
            break
        safe("delete objects", s3.delete_objects, Bucket=b, Delete={"Objects": objs, "Quiet": True})


def sweep_s3():
    s3 = boto3.client("s3", endpoint_url=EP, region_name=REGION, aws_access_key_id="test",
                      aws_secret_access_key="test", config=Config(s3={"addressing_style": "path"}, retries={"max_attempts": 5}))
    for b in (safe("list buckets", s3.list_buckets) or {}).get("Buckets", []):
        if mine(b["Name"]):
            log(f"s3: purge + delete bucket {b['Name']}")
            safe("bucket policy", s3.delete_bucket_policy, Bucket=b["Name"])
            purge_bucket(s3, b["Name"])
            safe("delete bucket", s3.delete_bucket, Bucket=b["Name"])


def sweep_cognito():
    cg = c("cognito-idp")
    token = None
    while True:
        kw = {"MaxResults": 60}
        if token:
            kw["NextToken"] = token
        resp = safe("list pools", cg.list_user_pools, **kw) or {}
        for p in resp.get("UserPools", []):
            if mine(p["Name"]):
                d = (safe("describe pool", cg.describe_user_pool, UserPoolId=p["Id"]) or {}).get("UserPool", {})
                if d.get("Domain"):
                    safe("delete domain", cg.delete_user_pool_domain, Domain=d["Domain"], UserPoolId=p["Id"])
                log(f"cognito: delete user pool {p['Name']} ({p['Id']})")
                safe("pool protection", cg.update_user_pool, UserPoolId=p["Id"], DeletionProtection="INACTIVE")
                safe("delete pool", cg.delete_user_pool, UserPoolId=p["Id"])
        token = resp.get("NextToken")
        if not token:
            break


def delete_policy(iam, arn):
    ents = safe("entities", iam.list_entities_for_policy, PolicyArn=arn) or {}
    for r in ents.get("PolicyRoles", []):
        safe("detach role", iam.detach_role_policy, RoleName=r["RoleName"], PolicyArn=arn)
    for u in ents.get("PolicyUsers", []):
        safe("detach user", iam.detach_user_policy, UserName=u["UserName"], PolicyArn=arn)
    for g in ents.get("PolicyGroups", []):
        safe("detach group", iam.detach_group_policy, GroupName=g["GroupName"], PolicyArn=arn)
    for v in (safe("versions", iam.list_policy_versions, PolicyArn=arn) or {}).get("Versions", []):
        if not v["IsDefaultVersion"]:
            safe("delete version", iam.delete_policy_version, PolicyArn=arn, VersionId=v["VersionId"])
    log(f"iam: delete policy {arn}")
    safe("delete policy", iam.delete_policy, PolicyArn=arn)


def sweep_iam():
    iam = c("iam")
    for page in iam.get_paginator("list_roles").paginate():
        for r in page.get("Roles", []):
            name = r["RoleName"]
            if not mine(name):
                continue
            for p in (safe("inline", iam.list_role_policies, RoleName=name) or {}).get("PolicyNames", []):
                safe("delete inline", iam.delete_role_policy, RoleName=name, PolicyName=p)
            for p in (safe("attached", iam.list_attached_role_policies, RoleName=name) or {}).get("AttachedPolicies", []):
                safe("detach", iam.detach_role_policy, RoleName=name, PolicyArn=p["PolicyArn"])
            for ip in (safe("profiles", iam.list_instance_profiles_for_role, RoleName=name) or {}).get("InstanceProfiles", []):
                safe("remove from profile", iam.remove_role_from_instance_profile,
                     InstanceProfileName=ip["InstanceProfileName"], RoleName=name)
            safe("permissions boundary", iam.delete_role_permissions_boundary, RoleName=name)
            log(f"iam: delete role {name}")
            safe("delete role", iam.delete_role, RoleName=name)
    for page in iam.get_paginator("list_policies").paginate(Scope="Local"):
        for p in page.get("Policies", []):
            if mine(p["PolicyName"]):
                delete_policy(iam, p["Arn"])
    for page in iam.get_paginator("list_instance_profiles").paginate():
        for ip in page.get("InstanceProfiles", []):
            if mine(ip["InstanceProfileName"]):
                for r in ip.get("Roles", []):
                    safe("remove role", iam.remove_role_from_instance_profile,
                         InstanceProfileName=ip["InstanceProfileName"], RoleName=r["RoleName"])
                safe("delete profile", iam.delete_instance_profile, InstanceProfileName=ip["InstanceProfileName"])
    for page in iam.get_paginator("list_users").paginate():
        for u in page.get("Users", []):
            name = u["UserName"]
            if not mine(name):
                continue
            for p in (safe("inline", iam.list_user_policies, UserName=name) or {}).get("PolicyNames", []):
                safe("delete inline", iam.delete_user_policy, UserName=name, PolicyName=p)
            for p in (safe("attached", iam.list_attached_user_policies, UserName=name) or {}).get("AttachedPolicies", []):
                safe("detach", iam.detach_user_policy, UserName=name, PolicyArn=p["PolicyArn"])
            for k in (safe("keys", iam.list_access_keys, UserName=name) or {}).get("AccessKeyMetadata", []):
                safe("delete key", iam.delete_access_key, UserName=name, AccessKeyId=k["AccessKeyId"])
            for g in (safe("groups", iam.list_groups_for_user, UserName=name) or {}).get("Groups", []):
                safe("remove from group", iam.remove_user_from_group, GroupName=g["GroupName"], UserName=name)
            safe("login profile", iam.delete_login_profile, UserName=name)
            log(f"iam: delete user {name}")
            safe("delete user", iam.delete_user, UserName=name)


def sweep_kms():
    kms = c("kms")
    keys = set()
    for page in kms.get_paginator("list_aliases").paginate():
        for a in page.get("Aliases", []):
            an = a["AliasName"]
            if an.startswith("alias/") and mine(an[len("alias/"):]):
                if a.get("TargetKeyId"):
                    keys.add(a["TargetKeyId"])
                log(f"kms: delete alias {an}")
                safe("delete alias", kms.delete_alias, AliasName=an)
    for page in kms.get_paginator("list_keys").paginate():
        for k in page.get("Keys", []):
            kid = k["KeyId"]
            if kid in keys:
                continue
            tags = (safe("key tags", kms.list_resource_tags, KeyId=kid) or {}).get("Tags", [])
            if tags_mine(tags):
                keys.add(kid)
                continue
            md = (safe("describe key", kms.describe_key, KeyId=kid) or {}).get("KeyMetadata", {})
            if md.get("KeyManager") == "CUSTOMER" and mine(md.get("Description", "").split(" ")[0]):
                keys.add(kid)
    for kid in keys:
        md = (safe("describe key", kms.describe_key, KeyId=kid) or {}).get("KeyMetadata", {})
        if md.get("KeyManager", "CUSTOMER") != "CUSTOMER":
            continue
        if md.get("KeyState") in ("PendingDeletion", "PendingReplicaDeletion"):
            continue
        log(f"kms: schedule deletion of key {kid}")
        safe("schedule key deletion", kms.schedule_key_deletion, KeyId=kid, PendingWindowInDays=7)


def sweep_logs():
    logs = c("logs")
    for page in logs.get_paginator("describe_log_groups").paginate():
        for g in page.get("logGroups", []):
            if LOG_RE.search(g["logGroupName"]):
                log(f"logs: delete log group {g['logGroupName']}")
                safe("delete log group", logs.delete_log_group, logGroupName=g["logGroupName"])


def sweep_misc():
    ssm = c("ssm")
    try:
        for page in ssm.get_paginator("describe_parameters").paginate():
            for p in page.get("Parameters", []):
                n = p["Name"]
                if mine(n.lstrip("/")) or LOG_RE.search(n):
                    safe("delete param", ssm.delete_parameter, Name=n)
    except Exception:  # noqa: BLE001
        pass
    sm = c("secretsmanager")
    try:
        for page in sm.get_paginator("list_secrets").paginate():
            for s in page.get("SecretList", []):
                if mine(s["Name"]) or tags_mine(s.get("Tags")):
                    safe("delete secret", sm.delete_secret, SecretId=s["ARN"], ForceDeleteWithoutRecovery=True)
    except Exception:  # noqa: BLE001
        pass
    sns = c("sns")
    try:
        for page in sns.get_paginator("list_topics").paginate():
            for t in page.get("Topics", []):
                if mine(t["TopicArn"].split(":")[-1]):
                    safe("delete topic", sns.delete_topic, TopicArn=t["TopicArn"])
    except Exception:  # noqa: BLE001
        pass


def name_tag(tags):
    for t in tags or []:
        if t.get("Key") == "Name":
            return t.get("Value")
    return None


def sweep_ec2():
    ec2 = c("ec2")
    vpcs = [v for v in (safe("vpcs", ec2.describe_vpcs) or {}).get("Vpcs", [])
            if not v.get("IsDefault") and (tags_mine(v.get("Tags")) or mine(name_tag(v.get("Tags"))))]
    vpc_ids = [v["VpcId"] for v in vpcs]

    # Security groups owned by the prefix (inside or outside our VPCs).
    sgs = (safe("sgs", ec2.describe_security_groups) or {}).get("SecurityGroups", [])
    doomed_sgs = [g for g in sgs if g["GroupName"] != "default" and
                  (g.get("VpcId") in vpc_ids or mine(g["GroupName"]) or tags_mine(g.get("Tags")))]
    for g in doomed_sgs:
        if g.get("IpPermissions"):
            safe("revoke ingress", ec2.revoke_security_group_ingress, GroupId=g["GroupId"], IpPermissions=g["IpPermissions"])
        if g.get("IpPermissionsEgress"):
            safe("revoke egress", ec2.revoke_security_group_egress, GroupId=g["GroupId"], IpPermissions=g["IpPermissionsEgress"])

    for vid in vpc_ids:
        enis = (safe("enis", ec2.describe_network_interfaces, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("NetworkInterfaces", [])
        for e in enis:
            if e.get("Attachment", {}).get("AttachmentId"):
                safe("detach eni", ec2.detach_network_interface, AttachmentId=e["Attachment"]["AttachmentId"], Force=True)
            safe("delete eni", ec2.delete_network_interface, NetworkInterfaceId=e["NetworkInterfaceId"])
        for ep in (safe("vpc endpoints", ec2.describe_vpc_endpoints, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("VpcEndpoints", []):
            safe("delete endpoint", ec2.delete_vpc_endpoints, VpcEndpointIds=[ep["VpcEndpointId"]])
        for ng in (safe("nat", ec2.describe_nat_gateways, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("NatGateways", []):
            safe("delete nat", ec2.delete_nat_gateway, NatGatewayId=ng["NatGatewayId"])

    for g in doomed_sgs:
        log(f"ec2: delete security group {g['GroupName']} ({g['GroupId']})")
        safe("delete sg", ec2.delete_security_group, GroupId=g["GroupId"])

    for vid in vpc_ids:
        for igw in (safe("igws", ec2.describe_internet_gateways, Filters=[{"Name": "attachment.vpc-id", "Values": [vid]}]) or {}).get("InternetGateways", []):
            safe("detach igw", ec2.detach_internet_gateway, InternetGatewayId=igw["InternetGatewayId"], VpcId=vid)
            safe("delete igw", ec2.delete_internet_gateway, InternetGatewayId=igw["InternetGatewayId"])
        for sn in (safe("subnets", ec2.describe_subnets, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("Subnets", []):
            safe("delete subnet", ec2.delete_subnet, SubnetId=sn["SubnetId"])
        for rt in (safe("rts", ec2.describe_route_tables, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("RouteTables", []):
            if any(a.get("Main") for a in rt.get("Associations", [])):
                continue
            for a in rt.get("Associations", []):
                safe("disassociate rt", ec2.disassociate_route_table, AssociationId=a["RouteTableAssociationId"])
            safe("delete rt", ec2.delete_route_table, RouteTableId=rt["RouteTableId"])
        for acl in (safe("acls", ec2.describe_network_acls, Filters=[{"Name": "vpc-id", "Values": [vid]}]) or {}).get("NetworkAcls", []):
            if not acl.get("IsDefault"):
                safe("delete acl", ec2.delete_network_acl, NetworkAclId=acl["NetworkAclId"])
        log(f"ec2: delete vpc {vid}")
        safe("delete vpc", ec2.delete_vpc, VpcId=vid)

    # Orphaned IGWs tagged for the prefix.
    for igw in (safe("igws", ec2.describe_internet_gateways) or {}).get("InternetGateways", []):
        if tags_mine(igw.get("Tags")) and not igw.get("Attachments"):
            safe("delete igw", ec2.delete_internet_gateway, InternetGatewayId=igw["InternetGatewayId"])


def main():
    steps = [sweep_scheduler, sweep_lambda, sweep_ecs, sweep_elb, sweep_rds, sweep_elasticache,
             sweep_dynamodb, sweep_sqs, sweep_s3, sweep_cognito, sweep_iam, sweep_kms, sweep_misc,
             sweep_ec2, sweep_logs]
    for step in steps:
        try:
            step()
        except Exception as exc:  # noqa: BLE001
            log(f"{step.__name__} failed: {exc}")


if __name__ == "__main__":
    main()

